import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry, DoubleSide } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const makeGradientMaterial = () => {
    const material = new MeshBasicNodeMaterial();
    const bottom = vec4(palette.surface, 1);
    const top = vec4(palette.ink, 1);
    material.colorNode = mix(bottom, top, smoothstep(0.02, 0.98, uv().y));
    material.side = DoubleSide;
    resources.push(material);
    return material;
  };

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    makeGradientMaterial()
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdrop.geometry);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: palette.surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const contactShadow = new Mesh(
    new CircleGeometry(1.35, 48),
    shadowMaterial
  );
  contactShadow.scale.set(1.55, 0.32, 1);
  contactShadow.position.set(0, -0.58, -0.08);
  root.add(contactShadow);
  resources.push(contactShadow.geometry, shadowMaterial);

  const panelMaterial = makeGradientMaterial();
  const panel = new Mesh(new PlaneGeometry(2.55, 1.48), panelMaterial);
  panel.position.set(0, 0, 0);
  root.add(panel);
  resources.push(panel.geometry);

  const panelEdgeMaterial = new MeshBasicNodeMaterial({
    color: palette.paper,
    transparent: true,
    opacity: 0.2
  });
  const panelEdge = new Mesh(new PlaneGeometry(2.55, 0.012), panelEdgeMaterial);
  panelEdge.position.set(0, 0.715, 0.025);
  root.add(panelEdge);
  resources.push(panelEdge.geometry, panelEdgeMaterial);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: palette.accent,
    transparent: true,
    opacity: 0.95
  });
  const accentBar = new Mesh(new PlaneGeometry(0.62, 0.035), accentMaterial);
  accentBar.position.set(-0.82, -0.48, 0.035);
  root.add(accentBar);
  resources.push(accentBar.geometry, accentMaterial);

  const imageOverlayMaterial = new MeshBasicNodeMaterial({
    color: palette.paper,
    transparent: true,
    opacity: 0.08,
    depthWrite: false,
    side: DoubleSide
  });
  const imageOverlay = new Mesh(
    new PlaneGeometry(2.55, 1.48),
    imageOverlayMaterial
  );
  imageOverlay.position.set(0, 0, 0.018);
  root.add(imageOverlay);
  resources.push(imageOverlay.geometry, imageOverlayMaterial);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) return;
      imageOverlayMaterial.map = texture;
      imageOverlayMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const text = String(item.text ?? '');
    const fontSize = item.typography?.fontSize ?? 39;
    const label = ctx.fontAtlas.createText(text, {
      fontSize,
      color: palette.paper,
      align: 'left',
      letterSpacingPx: item.role === 'label' ? 3 : 0
    });
    label.position.set(-0.82, 0.02, 0.06);
    root.add(label);
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') resource.dispose();
    }

    root.traverse((object) => {
      if (object.userData && typeof object.userData.cleanup === 'function' &&
          object !== root) {
        object.userData.cleanup();
      }
    });
  };

  void gsap;
  return root;
}
